export const metrics = {
  win:{title:'Villager win rate',direction:'Higher is better',table:6,maximum:100,format:v=>`${v}%`,delta:d=>`${d>0?'+':''}${Number(d.toFixed(1))} pp`},
  vote:{title:'Vote precision',direction:'Higher is better',table:8,maximum:100,format:v=>`${v.toFixed(1)}%`,delta:d=>`${d>0?'+':''}${d.toFixed(1)} pp`},
  belief:{title:'Belief error (RMSE)',direction:'Lower is better',table:7,maximum:1,format:v=>v.toFixed(3),delta:d=>`${d>0?'+':'−'}${Math.abs(d).toFixed(3)}`}
};
export function compareResults(model,metric){
  if(!results[model]||!metrics[metric])throw new RangeError('Unknown experiment or metric');
  const [baseline,coached]=results[model][metric];
  const difference=coached-baseline;
  return {baseline,coached,difference,improved:metric==='belief'?difference<0:difference>0,baselineWidth:baseline/metrics[metric].maximum*100,coachedWidth:coached/metrics[metric].maximum*100};
}
export function beliefError(scores,truth){
  if(!Array.isArray(scores)||!scores.length||scores.length!==truth.length||scores.some(x=>!Number.isFinite(x)||x<0||x>1)||truth.some(x=>x!==0&&x!==1))throw new RangeError('Invalid belief comparison');
  return Math.sqrt(scores.reduce((sum,x,i)=>sum+(x-truth[i])**2,0)/scores.length);
}
