  strategy:{tag:'Between games / persistent text',title:'The next match starts with a revised playbook.',description:'Villagers synthesise their game review, existing strategy and coaching feedback when enabled. Wolves self-reflect independently. Updated phase-specific rules are saved and injected into later prompts; model weights remain unchanged.',status:'NEXT GAME',code:'baseline: self-reflection + prior strategy\ncoached: self-reflection + feedback + strategy\npersist: phase-specific situational rules\nweight updates: none',trace:['Reflect','Save strategy','Next game']}
