export function villageFrame(index){
  if(!Number.isInteger(index)||index<0||index>=villageMoments.length)throw new RangeError('Unknown village moment');
  const moment=villageMoments[index];
  return {...moment,alive:7-moment.dead.length,wolves:2-moment.dead.filter(name=>villageCast.find(p=>p.name===name)?.role==='wolf').length};
}
export function startVillage(root){
  const get=id=>root.querySelector('#'+id),theatre=root.querySelector('.ww-theatre');
  if(!theatre)return;
  let index=0,revealed=false,timer=null;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const castNodes=villageCast.map(player=>{
    const node=document.createElement('div');node.className='ww-player';node.style.setProperty('--x',player.x+'%');node.style.setProperty('--y',player.y+'%');node.style.setProperty('--delay',(-player.x/20)+'s');
    const sprite=document.createElement('span');sprite.className='ww-sprite ww-player-sprite';sprite.setAttribute('aria-hidden','true');
    const name=document.createElement('span');name.className='ww-player-name';name.textContent=player.name;
    const badge=document.createElement('span');badge.className='ww-player-badge';
    node.append(sprite,name,badge);get('ww-cast').append(node);return {player,node,sprite,badge};
  });
  const progressNodes=villageMoments.map((moment,i)=>{
    const button=document.createElement('button');button.type='button';button.setAttribute('aria-label',`${i+1}. ${moment.round}`);button.title=moment.round;button.textContent=String(i+1);button.addEventListener('click',()=>{stop();index=i;draw();});get('ww-scene-progress').append(button);return button;
  });
  function stop(){if(timer!==null)clearInterval(timer);timer=null;get('ww-scene-play').setAttribute('aria-pressed','false');get('ww-scene-play').textContent=index===7?'↺ Play again':'▶ Play the story';}
  function draw(){
    const frame=villageFrame(index);theatre.dataset.sceneStep=String(index);theatre.dataset.light=frame.light;theatre.dataset.effect=frame.effect;
    const values={'round':frame.round,'count':`${frame.alive} alive · ${frame.wolves} ${frame.wolves===1?'wolf':'wolves'}`,'eyebrow':`${String(index+1).padStart(2,'0')} / ${frame.label}`,'title':frame.title,'copy':frame.copy,'bubble':frame.bubble,'insight':frame.insight};
    Object.entries(values).forEach(([key,value])=>get('ww-scene-'+key).textContent=value);
    castNodes.forEach(({player,node,sprite,badge})=>{const out=frame.dead.includes(player.name);node.classList.toggle('is-out',out);node.classList.toggle('is-active',frame.active.includes(player.name));sprite.dataset.sprite=revealed||out?player.role:'villager';badge.textContent=out?'Exiled · Werewolf':revealed?(player.role==='wolf'?'Werewolf':player.role[0].toUpperCase()+player.role.slice(1)):'Hidden role';});
    progressNodes.forEach((button,i)=>{button.setAttribute('aria-current',i===index?'step':'false');button.classList.toggle('is-past',i<index);});
    root.querySelectorAll('[data-phase]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.phase===frame.phase)));
    const phase=phases[frame.phase];['tag','title','description','status'].forEach(key=>get('ww-phase-'+key).textContent=phase[key]);
    const trace=get('ww-phase-trace');trace.replaceChildren();phase.trace.forEach((value,i)=>{if(i)trace.append(document.createElement('i'));const span=document.createElement('span');span.textContent=value;trace.append(span);});
    get('ww-scene-next').disabled=false;
    if(index===7)stop();
  }
  get('ww-scene-next').addEventListener('click',()=>{stop();index=(index+1)%villageMoments.length;draw();});
  get('ww-scene-reset').addEventListener('click',()=>{stop();index=0;draw();});
  get('ww-scene-reveal').addEventListener('click',()=>{revealed=!revealed;get('ww-scene-reveal').setAttribute('aria-pressed',String(revealed));get('ww-scene-reveal').textContent=revealed?'Hide the roles':'Reveal hidden roles';draw();});
  get('ww-scene-play').addEventListener('click',()=>{
    if(timer!==null){stop();return;}if(index===7){index=0;draw();}
    get('ww-scene-play').setAttribute('aria-pressed','true');get('ww-scene-play').textContent='Ⅱ Pause the story';
    timer=setInterval(()=>{index=Math.min(7,index+1);draw();},7000);
  });
  const phaseStarts={night:0,debate:2,vote:3,coach:6,strategy:7};
  root.querySelectorAll('[data-phase]').forEach(button=>button.addEventListener('click',()=>{stop();index=phaseStarts[button.dataset.phase];draw();}));
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
  window.addEventListener('hashchange',stop);
  reduced.addEventListener('change',stop);
  new MutationObserver(()=>{if(document.documentElement.classList.contains('motion-paused')||document.body.classList.contains('motion-paused'))stop();}).observe(document.documentElement,{attributes:true,attributeFilter:['class'],subtree:true});
  draw();
}
export function startWerewolf(root){
  if(!root)return;
  const get=id=>root.querySelector('#'+id);
  const text=(id,value)=>get(id).textContent=value;
  root.querySelectorAll('[data-ww-scroll]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();get(a.dataset.wwScroll).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
  root.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>{
    root.querySelectorAll('[data-role]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
    roles[button.dataset.role].forEach((value,i)=>text(['ww-role-name','ww-role-description','ww-role-knows','ww-role-unknown','ww-role-task'][i],value));
  }));
  root.querySelectorAll('[data-phase]').forEach(button=>button.addEventListener('click',()=>{
    root.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
    const phase=phases[button.dataset.phase];
    ['tag','title','description','status'].forEach(key=>text('ww-phase-'+key,phase[key]));
    const trace=get('ww-phase-trace');trace.replaceChildren();
    phase.trace.forEach((value,i)=>{if(i)trace.append(document.createElement('i'));const node=document.createElement('span');node.textContent=value;trace.append(node);});
  }));
  startVillage(root);
  let replayModel=31,replayStep=0;
  function drawReplay(){
    const item=replay[replayModel][replayStep];
    text('ww-replay-stage-label',item.label);text('ww-replay-headline',item.headline);text('ww-replay-context',item.context);text('ww-replay-quote',item.quote);text('ww-replay-seal',`Game 3 · coached ${replayModel}B condition`);text('ww-replay-position',`${replayStep+1} / 3`);
    get('ww-replay-prev').disabled=false;get('ww-replay-next').disabled=false;
    root.querySelectorAll('.ww-replay-progress span').forEach((span,i)=>span.classList.toggle('is-active',i===replayStep));
  }
  root.querySelectorAll('[data-replay-model]').forEach(button=>button.addEventListener('click',()=>{replayModel=Number(button.dataset.replayModel);root.querySelectorAll('[data-replay-model]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));drawReplay();}));
  get('ww-replay-prev').addEventListener('click',()=>{replayStep=(replayStep+2)%3;drawReplay();});get('ww-replay-next').addEventListener('click',()=>{replayStep=(replayStep+1)%3;drawReplay();});
  let resultModel=31;
  function drawResults(){
    const key=get('ww-metric').value,m=metrics[key],r=compareResults(resultModel,key);
    text('ww-metric-title',m.title);text('ww-metric-direction',m.direction);text('ww-base-value',m.format(r.baseline));text('ww-coach-value',m.format(r.coached));text('ww-axis-max',key==='belief'?'1.0':'100%');text('ww-result-delta',m.delta(r.difference));
    get('ww-base-bar').style.width=r.baselineWidth+'%';get('ww-coach-bar').style.width=r.coachedWidth+'%';get('ww-result-delta').style.color=r.improved?'#315d45':r.difference===0?'#59665c':'#a13e2e';
    const descriptions={
      '31-win':['Advice became better decisions.','Coached 31B villagers won 74 of 100 games, compared with 55 without coaching. A 19-percentage-point gain.'],
      '12-win':['More advice. The same win rate.','Both 12B conditions won just 1 of 100 games. Coaching did not improve the reported win rate.'],
      '31-vote':['More votes found actual wolves.','Vote precision increased from 39.7% to 55.9%. Coached villagers more often targeted an actual wolf.'],
      '12-vote':['The extra guidance did not translate.','Vote precision fell from 7.6% to 4.2%. The smaller model’s written advice did not produce better targeting.'],
      '31-belief':['Beliefs moved closer to the hidden roles.','RMSE decreased from 0.417 to 0.387. Lower error means suspicion scores better aligned with the true roles.'],
      '12-belief':['Coaching worsened belief calibration.','RMSE rose from 0.591 to 0.618. The smaller model became less accurate at aligning suspicion with hidden roles.']
    };
    const [headline,meaning]=descriptions[`${resultModel}-${key}`];text('ww-result-headline',headline);text('ww-result-meaning',meaning);text('ww-metric-source',`Source: report Table ${m.table}. 100 games per condition${key==='belief'?'; RMSE aggregated over evaluated comparisons':''}.`);
  }
  root.querySelectorAll('[data-result-model]').forEach(button=>button.addEventListener('click',()=>{resultModel=Number(button.dataset.resultModel);root.querySelectorAll('[data-result-model]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));drawResults();}));get('ww-metric').addEventListener('change',drawResults);
  const beliefs=['villager','wolf','other'];
  function drawBeliefs(){const scores=beliefs.map(name=>Number(get('ww-belief-'+name).value)),error=beliefError(scores,[0,1,0]);beliefs.forEach((name,i)=>text('ww-belief-'+name+'-value',scores[i].toFixed(2)));text('ww-rmse',error.toFixed(3));get('ww-rmse-fill').style.width=(100*error)+'%';text('ww-belief-meaning',error<.01?'Perfect alignment in this example: innocent players are trusted and the wolf is identified.':error<.35?'The scores are partly aligned with the hidden roles. Any remaining uncertainty or misidentification still contributes to error.':error<.65?'There is substantial uncertainty or misidentification. A confident suspicion is useful only when it matches the hidden role.':'High error: these beliefs point away from the true roles. Confidently accusing innocents can be worse than remaining uncertain.');}
  beliefs.forEach(name=>get('ww-belief-'+name).addEventListener('input',drawBeliefs));get('ww-reset-beliefs').addEventListener('click',()=>{[.1,.9,.5].forEach((value,i)=>get('ww-belief-'+beliefs[i]).value=value);drawBeliefs();});drawReplay();drawResults();drawBeliefs();
}
if(typeof document!=='undefined'){
  startWerewolf(document.querySelector('.werewolf-native'));
  const observer=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('ww-in-view',entry.isIntersecting&&!entry.target.closest('[hidden]'))),{threshold:.15});
  document.querySelectorAll('.ww-work-cover,.ww-hero').forEach(el=>observer.observe(el));
  function observeActive(){document.querySelectorAll('.ww-work-cover,.ww-hero').forEach(el=>{el.classList.remove('ww-in-view');observer.unobserve(el);if(!el.closest('[hidden]'))observer.observe(el);});}
  window.addEventListener('hashchange',observeActive);
  document.addEventListener('visibilitychange',()=>{document.querySelectorAll('.ww-in-view').forEach(el=>el.style.animationPlayState=document.hidden?'paused':'');if(document.hidden)document.querySelectorAll('.ww-hero-art,.ww-work-cover img').forEach(el=>el.style.animationPlayState='paused');else document.querySelectorAll('.ww-hero-art,.ww-work-cover img').forEach(el=>el.style.animationPlayState='');});
}
